import { useState } from "react";

import {
  DialogBackdrop,
  DialogCloseTrigger,
  DialogContent,
  DialogDescription,
  DialogPortal,
  DialogPositioner,
  DialogRoot,
  DialogTitle,
} from "@/registry/thornberry/components/dialog";
import { Kbd } from "@/registry/thornberry/components/kbd";
import {
  GLOBAL_HOTKEYS,
  hotkeyLabel,
  useHotkeys,
} from "@/registry/thornberry/components/use-hotkeys";

type GlobalHotkey = keyof typeof GLOBAL_HOTKEYS;

interface Shortcut {
  /** `react-hotkeys-hook` binding, e.g. `mod+k` or `shift+slash` */
  keys: string;
  /** What the shortcut does */
  label: string;
}

interface ShortcutGroup {
  title: string;
  /** Hint shown beside the heading (e.g. "Hover a card, then press:") */
  hint?: string;
  shortcuts: Shortcut[];
}

/** How each global hotkey reads in the list, in display order */
const GLOBAL_LABELS: Record<GlobalHotkey, string> = {
  commandPalette: "Open command palette",
  showShortcuts: "Show keyboard shortcuts",
  toggleSidebar: "Toggle sidebar",
  toggleTheme: "Toggle light/dark theme",
};

interface ShortcutsDialogProps {
  /**
   * Global hotkeys the app binds, listed first under "General". Defaults to
   * every one except `toggleSidebar`; include it when the app has a sidebar.
   */
  globals?: GlobalHotkey[];
  /** App-wide shortcuts appended to the "General" group */
  general?: Shortcut[];
  /** Product shortcut groups, listed after "General" */
  groups?: ShortcutGroup[];
  /** Controlled open state, e.g. to open the list from the command palette */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

const DEFAULT_GLOBALS: GlobalHotkey[] = [
  "commandPalette",
  "showShortcuts",
  "toggleTheme",
];

/**
 * Keyboard shortcuts list, opened with `?` (`GLOBAL_HOTKEYS.showShortcuts`).
 * Mount once in the app root, next to the command palette, and pass the
 * product's own shortcuts so every key the app binds is discoverable in one
 * place. Labels render with {@link hotkeyLabel}, so they match the platform.
 */
const ShortcutsDialog = ({
  globals = DEFAULT_GLOBALS,
  general = [],
  groups = [],
  open: openProp,
  onOpenChange,
}: ShortcutsDialogProps) => {
  const [openState, setOpenState] = useState(false);
  const open = openProp ?? openState;

  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next);
    onOpenChange?.(next);
  };

  useHotkeys(GLOBAL_HOTKEYS.showShortcuts, () => setOpen(!open), [open]);

  const ordered = (Object.keys(GLOBAL_LABELS) as GlobalHotkey[]).filter((key) =>
    globals.includes(key),
  );

  const allGroups: ShortcutGroup[] = [
    {
      title: "General",
      shortcuts: [
        ...ordered.map((key) => ({
          keys: GLOBAL_HOTKEYS[key],
          label: GLOBAL_LABELS[key],
        })),
        ...general,
      ],
    },
    ...groups,
  ];

  return (
    <DialogRoot
      open={open}
      onOpenChange={(details) => setOpen(details.open)}
      lazyMount
      unmountOnExit
    >
      <DialogPortal>
        <DialogBackdrop />

        <DialogPositioner>
          <DialogContent className="max-h-full overflow-y-auto">
            <DialogCloseTrigger />

            <div className="flex flex-col gap-1.5">
              <DialogTitle>Keyboard shortcuts</DialogTitle>
              <DialogDescription>
                Press <Kbd>{hotkeyLabel(GLOBAL_HOTKEYS.showShortcuts)}</Kbd>{" "}
                anytime to open this list.
              </DialogDescription>
            </div>

            <div className="flex flex-col gap-5">
              {allGroups
                .filter((group) => group.shortcuts.length > 0)
                .map((group) => (
                  <section key={group.title} className="flex flex-col gap-2">
                    <div className="flex items-baseline gap-2">
                      <h3 className="text-foreground text-sm font-medium">
                        {group.title}
                      </h3>
                      {group.hint && (
                        <span className="text-muted-foreground text-xs">
                          {group.hint}
                        </span>
                      )}
                    </div>

                    <ul className="divide-border flex flex-col divide-y">
                      {group.shortcuts.map((shortcut) => (
                        <li
                          key={`${shortcut.keys}-${shortcut.label}`}
                          className="flex items-center justify-between gap-4 py-1.5"
                        >
                          <span className="text-muted-foreground text-sm">
                            {shortcut.label}
                          </span>
                          <Kbd>{hotkeyLabel(shortcut.keys)}</Kbd>
                        </li>
                      ))}
                    </ul>
                  </section>
                ))}
            </div>
          </DialogContent>
        </DialogPositioner>
      </DialogPortal>
    </DialogRoot>
  );
};

export { type Shortcut, type ShortcutGroup, ShortcutsDialog };

import { Dialog as ArkDialog } from "@ark-ui/react/dialog";
import { Portal } from "@ark-ui/react/portal";
import { X } from "lucide-react";

import { cn } from "@/lib/utils";

import type { ComponentProps } from "react";

const DialogProvider = ArkDialog.RootProvider;
const DialogContext = ArkDialog.Context;
const DialogRoot = ArkDialog.Root;

/**
 * Portals the dialog's backdrop and positioner to the document body. Without it
 * the `fixed inset-0` backdrop and positioner render inline in the DOM, so any
 * ancestor with a `transform`, `filter`, or `backdrop-filter` (page/route
 * transitions, blurred panels) becomes their containing block and the overlay no
 * longer covers the full viewport. Wrap every dialog's backdrop + positioner in
 * this so they always resolve against the viewport.
 */
const DialogPortal = Portal;

const DialogTrigger = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Trigger>) => (
  <ArkDialog.Trigger className={cn("", className)} {...rest} />
);

const DialogBackdrop = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Backdrop>) => (
  <ArkDialog.Backdrop
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 fixed inset-0 z-50 bg-background/80 backdrop-blur-sm data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const DialogPositioner = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Positioner>) => (
  <ArkDialog.Positioner
    className={cn(
      // `p-4` keeps a gutter so a dialog never runs edge to edge on a phone
      "fixed inset-0 z-50 flex items-center justify-center p-4",
      className,
    )}
    {...rest}
  />
);

/**
 * Dialog panel. Capped to the positioner's height and scrolls past it, so a tall
 * dialog never runs off screen with its actions unreachable
 */
const DialogContent = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Content>) => (
  <ArkDialog.Content
    className={cn(
      "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-top-[2%] data-[state=open]:slide-in-from-top-[2%] relative grid max-h-full w-full max-w-lg gap-4 overflow-y-auto overscroll-contain border bg-background p-6 rounded-lg shadow-lg duration-200 data-[state=closed]:animate-out data-[state=open]:animate-in",
      className,
    )}
    {...rest}
  />
);

const DialogTitle = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Title>) => (
  <ArkDialog.Title
    className={cn(
      "font-semibold text-lg leading-none tracking-tight",
      className,
    )}
    {...rest}
  />
);

const DialogDescription = ({
  className,
  ...rest
}: ComponentProps<typeof ArkDialog.Description>) => (
  <ArkDialog.Description
    className={cn("text-muted-foreground text-sm", className)}
    {...rest}
  />
);

const DialogCloseTrigger = ({
  className,
  children,
  asChild,
  ...rest
}: ComponentProps<typeof ArkDialog.CloseTrigger>) => {
  // If there are no children, render the default X icon
  if (!children) {
    return (
      <ArkDialog.CloseTrigger
        className={cn(
          "absolute top-4 right-4 cursor-pointer rounded opacity-70 outline-none ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 disabled:pointer-events-none",
          className,
        )}
        {...rest}
      >
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </ArkDialog.CloseTrigger>
    );
  }

  // If children are provided, use them inside the CloseTrigger
  // This is useful for creating buttons that close the dialog
  return (
    <ArkDialog.CloseTrigger className={className} asChild={asChild} {...rest}>
      {children}
    </ArkDialog.CloseTrigger>
  );
};

export {
  DialogBackdrop,
  DialogCloseTrigger,
  DialogContent,
  DialogContext,
  DialogDescription,
  DialogPortal,
  DialogPositioner,
  DialogProvider,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
};

import { cn } from "@/lib/utils";

import type { ComponentProps } from "react";

/**
 * Keyboard-shortcut hint. Renders a `<kbd>` chip used to surface a shortcut next
 * to an action (e.g. a "C" badge on a Create button, or in a tooltip/menu).
 */
const Kbd = ({ className, ...rest }: ComponentProps<"kbd">) => (
  <kbd
    data-slot="kbd"
    className={cn(
      "pointer-events-none inline-flex h-5 w-fit min-w-5 select-none items-center justify-center gap-0.5 rounded border bg-muted px-1 font-medium font-sans text-[0.625rem] text-muted-foreground uppercase leading-none",
      className,
    )}
    {...rest}
  />
);

export { Kbd };

import { useHotkeys } from "react-hotkeys-hook";

/**
 * Shared hotkey surface for Omni apps: a single import source for
 * `react-hotkeys-hook`, the normalized global bindings every product shares, and
 * a label helper so shortcuts render identically product to product. Apps extend
 * {@link GLOBAL_HOTKEYS} with their own keys and bind them with {@link useHotkeys}.
 */

/** Shortcuts every Omni app binds the same way. Extend per app as needed. */
export const GLOBAL_HOTKEYS = {
  /** Toggle the command palette. */
  commandPalette: "mod+k",
  /** Toggle light/dark theme. */
  toggleTheme: "t",
  /** Collapse or expand the sidebar. */
  toggleSidebar: "b",
  /** Show the keyboard shortcuts list (the `?` key). */
  showShortcuts: "shift+slash",
} as const;

const isApplePlatform = () =>
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad|iPod/.test(navigator.platform);

/**
 * Named `react-hotkeys-hook` key tokens that should render as their glyph
 * rather than the raw word (e.g. `slash` as `/`). The lookup is case-insensitive
 * via the token's lowercase form.
 */
const NAMED_KEY_GLYPHS: Record<string, string> = {
  slash: "/",
  space: "Space",
  escape: "Esc",
  esc: "Esc",
  enter: "Enter",
  return: "Enter",
  arrowup: "↑",
  arrowdown: "↓",
  arrowleft: "←",
  arrowright: "→",
  comma: ",",
  period: ".",
  dot: ".",
};

/**
 * Render a `react-hotkeys-hook` binding string as a human label, e.g. `mod+k`
 * becomes `⌘K` on Apple platforms and `Ctrl+K` elsewhere. Use for shortcut hints
 * (pair with the `Kbd` chip) so the displayed key matches the bound key.
 *
 * Named keys render as their glyph (`slash` becomes `/`, `escape` becomes `Esc`,
 * the arrows become `↑↓←→`), and the `shift+slash` binding (the `?` key) renders
 * as `?` on every platform rather than a literal `⇧/` / `Shift+Slash`.
 */
export const hotkeyLabel = (hotkey: string): string => {
  const apple = isApplePlatform();

  const parts = hotkey.split("+");

  // `shift+slash` is how products bind the `?` key (e.g. runa's "show keyboard
  // shortcuts"); render it as the single `?` glyph regardless of part order or
  // platform
  const normalized = parts.map((part) => part.trim().toLowerCase());
  if (
    normalized.length === 2 &&
    normalized.includes("shift") &&
    normalized.includes("slash")
  ) {
    return "?";
  }

  return parts
    .map((part) => {
      if (part === "mod") return apple ? "⌘" : "Ctrl";
      if (part === "shift") return apple ? "⇧" : "Shift";
      if (part === "alt") return apple ? "⌥" : "Alt";
      if (part === "ctrl") return apple ? "⌃" : "Ctrl";
      const glyph = NAMED_KEY_GLYPHS[part.toLowerCase()];
      if (glyph) return glyph;
      return part.length === 1 ? part.toUpperCase() : part;
    })
    .join(apple ? "" : "+");
};

export { useHotkeys };

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};
